const sd=$getWorkflowStaticData('global');
sd.syncResults=[];
const launch=sd.launch||{};
const cf=String(launch.clientFilter||'');
const nowIL=$now.setZone('Asia/Jerusalem');
const yesterday=nowIL.minus({days:1}).toFormat('yyyy-MM-dd');
const today=nowIL.toFormat('yyyy-MM-dd');
// Scheduled runs sync every PV client. A launched run with a Client on its launch row syncs that client only.
const all=$('Get PV Clients').all().filter(it=>it.json&&it.json.id);
const picked=cf?all.filter(it=>it.json.id===cf):all;
sd.syncScope=cf?(picked.length?'one client (on demand)':'client filter matched no PV client'):'all clients';
// Nothing to loop over: emit one placeholder so the Any Clients? gate can route straight to the run log.
if(!picked.length) return [{ json: { _empty:true } }];
return picked.map(it=>{
  const j=it.json; const f=j.fields||j;
  return { json: { clientRecId:j.id, clientName:f['Client']||'', pvWorkspace:String(f['PlusVibe Workspace ID']||'').trim(), yesterday, today } };
});

const sd=$getWorkflowStaticData('global');
const launch=sd.launch||{};
const results=sd.syncResults||[];
const totalInboxes=results.reduce((s,r)=>s+(r.inboxes||0),0);
const totalWritten=results.reduce((s,r)=>s+(r.written||0),0);
const totalFailed=results.reduce((s,r)=>s+(r.failed||0),0);
const lines=results.map(r=>'- **'+r.client+':** '+r.inboxes+' inboxes, '+r.written+' written'+(r.failed?', '+r.failed+' pull failure(s)':'')+(r.ok?'':' (WRITE MISMATCH)'));
const parts=['**'+results.length+' client(s), '+totalInboxes+' inbox(es), '+totalFailed+' pull failure(s)**','**Scope:** '+(sd.syncScope||'all clients')].concat(lines);
if(launch.clientFilter && !results.length) parts.push('**Skipped (1, client filter matched no PlusVibe client)**');
const row={
  'Automation':'Sync PlusVibe Inboxes to Hub',
  'Status': totalFailed>0? 'Succeeded with errors':'Succeeded',
  'Run at': $now.toISO(),
  'Records In': totalInboxes,
  'Records Out': totalWritten,
  'Errors': totalFailed,
  'Target': 'Inboxes',
  'Trigger': launch.trigger||'schedule',
  'Execution ID': String($execution.id),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
  'Duration s': Math.round(($now.toMillis()-(launch.startedAt||$now.toMillis()))/1000),
  'Description': parts.join('\n')
};
// Client is attached only when the run served exactly one client; never an empty link array.
if(launch.clientFilter) row['Client']=[launch.clientFilter];
return [{ json: row }];

const cw=$('Loop Over Clients').first().json;
const pages=$('List Email Accounts').all().map(i=>i&&i.json).filter(j=>j&&typeof j==='object');
const accounts=[];
for(const p of pages){ if(Array.isArray(p.accounts)) accounts.push(...p.accounts); }
return accounts.map(a=>{
  const payload=a.payload||{};
  const hs=(payload.analytics&&payload.analytics.health_scores)||{};
  const rr=(payload.analytics&&payload.analytics.reply_rates)||{};
  const created=String(a.timestamp_created||'').slice(0,10) || '2020-01-01';
  return { json: {
    email:a.email||'', accountId:a.id||'', status:a.status||'', warmup:a.warmup_status||'', provider:a.provider||'',
    dailyLimit:payload.daily_limit||0, warmupHealth:hs['7d_overall_warmup_health'], missWarmupRate:hs['1d_miss_warmup_rate'], bounceRate3d:hs['3d_bounce_rate'], replyRate7d:rr['7d_replyrate'],
    tagIds: Array.isArray(payload.tags)?payload.tags:[],
    url:'https://api.plusvibe.ai/api/v1/account/email-stats?workspace_id='+cw.pvWorkspace+'&email_acc_id='+a.id+'&start_date='+created+'&end_date='+cw.today
  } };
});

const cw=$('Loop Over Clients').first().json;
const accounts=$('Prep Account Stat Calls').all().map(i=>i&&i.json).filter(Boolean);
let stats=[];
try{ stats=$('Account Stats').all().map(i=>i&&i.json).filter(Boolean); }catch(e){ stats=[]; }
let tagItems=[];
try{ tagItems=$('List Tags').all().map(i=>i&&i.json).filter(Boolean); }catch(e){ tagItems=[]; }
const tagMap={};
for(const t of tagItems){ if(t&&t._id) tagMap[t._id]=t.name||t._id; }
const num=(v)=>{ if(typeof v==='number') return v; const n=parseFloat(v); return isNaN(n)?0:n; };
if(!accounts.length) return [{ json: { _keepAlive:true } }];
return accounts.map((a,i)=>{
  const raw=stats[i]||{};
  const failed=!raw.header || raw.status>=400 || !!raw.error_name;
  const s=raw.header||{};
  const domain=(a.email.split('@')[1]||a.email).toLowerCase();
  const tagNames=(a.tagIds||[]).map(id=>tagMap[id]||id).join(', ');
  return { json: {
    'Inbox': a.email,
    'Account ID': a.accountId,
    'Client': [cw.clientRecId],
    'Domain': domain,
    'Status': a.status,
    'Warmup Status': a.warmup,
    'Provider': a.provider,
    'Daily Limit': a.dailyLimit,
    'Tags': tagNames,
    'Sent (All-Time)': failed?0:num(s.total_sent_count),
    'Replies (All-Time)': failed?0:num(s.total_reply_count),
    'OOO Replies (All-Time)': failed?0:num(s.total_ooo_reply_count),
    'Positive (All-Time)': failed?0:num(s.total_pos_reply_count),
    'Bounced (All-Time)': failed?0:num(s.total_bounce_count),
    'Warmup Health (7d)': (a.warmupHealth==null)?null:a.warmupHealth,
    'Miss Warmup Rate': (a.missWarmupRate==null)?null:a.missWarmupRate,
    'Bounce Rate (3d)': (a.bounceRate3d==null)?null:a.bounceRate3d,
    'Reply Rate (7d)': (a.replyRate7d==null)?null:a.replyRate7d,
    'Last Synced': $now.toISO(),
    _failed: failed
  } };
});

const sd=$getWorkflowStaticData('global');
if(!Array.isArray(sd.syncResults)) sd.syncResults=[];
const cw=$('Loop Over Clients').first().json;
let rows=[]; try{ rows=$('Build Inbox Rows').all().map(i=>i.json).filter(r=>r&&r['Account ID']); }catch(e){}
let written=[]; try{ written=$('Upsert Inboxes').all().map(i=>i.json); }catch(e){}
const seen=rows.length;
const failedCount=rows.filter(r=>r._failed).length;
const ok=!(seen>0 && written.length===0);
sd.syncResults.push({ client:cw.clientName, inboxes:seen, written:written.length, failed:failedCount, ok });
return [{ json: { done:true } }];

const cw=$('Loop Over Clients').first().json;
const rows=$('Build Inbox Rows').all().map(i=>i&&i.json).filter(Boolean);
const domains=[...new Set(rows.filter(r=>r.Domain).map(r=>r.Domain))];
if(!domains.length) return [{ json: { _keepAlive:true } }];
return domains.map(d=>({ json: { 'Domain': d, 'Client': [cw.clientRecId], 'Last Synced': $now.toISO() } }));

const rows=$('Build Inbox Rows').all().map(i=>i&&i.json).filter(Boolean);
let domainRecs=[]; try{ domainRecs=$('Upsert Domains').all().map(i=>i.json).filter(Boolean); }catch(e){}
const domainMap={};
for(const d of domainRecs){ const nm = d.fields ? d.fields['Domain'] : d['Domain']; if(d.id && nm) domainMap[nm]=d.id; }
if(!rows.length || (rows.length===1 && rows[0]._keepAlive)) return [{ json: { _keepAlive:true } }];
return rows.map(r=>{
  const domainRecId = r.Domain ? domainMap[r.Domain] : null;
  return { json: Object.assign({}, r, { 'Domain Link': domainRecId?[domainRecId]:[] }) };
});

// Run Context: one shape for every run, launched or scheduled.
// sd.launch.recordId  = the Hub Automations row this run was launched from ('' on a schedule)
// sd.launch.trigger   = 'form' when launched from the Hub, 'schedule' otherwise
// sd.launch.clientFilter = the launch row's Client link (one record id) to scope the run to one client; '' = all clients
const sd=$getWorkflowStaticData('global');
let launch=null;
try{ const r=$('Fetch Launch Record').first().json; if(r&&r.id) launch=r; }catch(e){}
const f=(launch&&launch.fields)||launch||{};
const cl=Array.isArray(f.Client)&&f.Client.length?f.Client[0]:'';
const clientFilter=(cl&&typeof cl==='object')?String(cl.id||''):String(cl||'');
sd.launch={ recordId: launch?String(launch.id):'', trigger: launch?'form':'schedule', clientFilter, startedAt:$now.toMillis() };
return [{ json: Object.assign({}, sd.launch) }];
